import openpyxl
wb=openpyxl.load_workbook(\"documents/fda-inspection-checklist.xlsx\")
for ws in wb:
  print(\"=== \",ws.title, ws.dimensions)
  for r in ws.iter_rows(values_only=True):
    if any(v is not None for v in r): print(\" | \".join(\"\" if v is None else str(v) for v in r))
"
